H.background();
const v = H.plot2d({ xMin: 0, xMax: 4 * Math.PI, yMin: -5, yMax: 5 });
v.grid(); v.axes();
const A1 = Math.max(0, P.A1), A2 = Math.max(0, P.A2), phaseDeg = P.phase;
const phi = phaseDeg * Math.PI / 180;
const k = 1, omega = 1.2;
const y1 = x => A1 * Math.sin(k * x - omega * t);
const y2 = x => A2 * Math.sin(k * x - omega * t + phi);
// Component waves (faint) + their superposition (bold).
v.fn(y1, { color: H.colors.accent, width: 1.8 });
v.fn(y2, { color: H.colors.accent2, width: 1.8 });
v.fn(x => y1(x) + y2(x), { color: H.colors.good, width: 3 });
// Resultant amplitude from phasor addition: Ar = sqrt(A1^2 + A2^2 + 2 A1 A2 cos phi)
const Ar = Math.sqrt(A1 * A1 + A2 * A2 + 2 * A1 * A2 * Math.cos(phi));
// Mark the resultant amplitude as dashed envelope lines.
v.line(0, Ar, 4 * Math.PI, Ar, { color: H.colors.violet, width: 1.2, dash: [5, 5] });
v.line(0, -Ar, 4 * Math.PI, -Ar, { color: H.colors.violet, width: 1.2, dash: [5, 5] });
// Riding dot on the resultant.
const xs = (t * 0.9) % (4 * Math.PI);
v.dot(xs, y1(xs) + y2(xs), { r: 6, fill: H.colors.warn });
const kind = Math.abs(((phaseDeg % 360) + 360) % 360) < 30 || Math.abs(((phaseDeg % 360) + 360) % 360 - 360) < 30 ? "constructive (in phase)" : (Math.abs(((phaseDeg % 360) + 360) % 360 - 180) < 30 ? "destructive (out of phase)" : "partial");
H.text("Superposition: waves add point-by-point", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A1 = " + A1.toFixed(1) + "   A2 = " + A2.toFixed(1) + "   phase = " + phaseDeg.toFixed(0) + " deg   ->   resultant A = " + Ar.toFixed(2) + "   (" + kind + ")", 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "wave 1", color: H.colors.accent }, { label: "wave 2", color: H.colors.accent2 }, { label: "sum", color: H.colors.good }], H.W - 150, 28);
